"use client";

import { useCallback, useState, type CSSProperties } from "react";
import { useClinkPhysics, type Clink } from "../hooks/useClinkPhysics";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";

/**
 * Chapter 03 — the soju table. The `drag-physics` technique. A stage of
 * draggable soju glasses and a skewer you can fling; on release they coast on
 * inertia and spring back home, and when two bodies' circles overlap a *clink*
 * fires — a pink/amber spark SFX pops at the midpoint and the bodies take a
 * small knockback. `useClinkPhysics` owns the rAF + the physics; this
 * component owns only the (rare) clink-spark state.
 *
 * Rest positions are declared in data-rest-x / data-rest-y (in px, local to
 * the stage) so the hook can snapshot them at mount. The hook is fine-pointer
 * only — on touch and under reduced motion the glasses sit at rest and the
 * table is a calm, readable still life (the drag is a flourish, not a gate).
 *
 * Each draggable body is keyboard-reachable (tabindex="0") with a visible
 * amber focus halo; keyboard users get the same table, the drag is an
 * enhancement.
 *
 * The clink sparks are positioned with `left/top` (not transform) so they
 * don't fight the keyframe scale on `.ns-spark` — and they auto-clear after
 * their animation via a settling timeout.
 */
const BODIES = [
  {
    key: "glass-1",
    kind: "glass" as const,
    restX: 130,
    restY: 150,
    r: 30,
    label: "소주잔 한 잔 / soju glass",
  },
  {
    key: "glass-2",
    kind: "glass" as const,
    restX: 300,
    restY: 210,
    r: 30,
    label: "소주잔 두 잔 / second glass",
  },
  {
    key: "glass-3",
    kind: "glass" as const,
    restX: 200,
    restY: 320,
    r: 30,
    label: "소주잔 셋 / third glass",
  },
  {
    key: "skewer",
    kind: "skewer" as const,
    restX: 500,
    restY: 180,
    r: 40,
    label: "꼬치 / skewer",
  },
] as const;

const CLINK_SFX = ["짠! ", "乾杯! ", "CLINK! ", "찰칵! "] as const;

export default function ClinkDrag() {
  const reduced = usePrefersReducedMotion();
  const [sparks, setSparks] = useState<Clink[]>([]);

  // Stable callback: the hook's effect deps include onClink, so it must not
  // change identity per render. We push a spark and schedule its removal.
  const onClink = useCallback((c: Clink) => {
    setSparks((prev) => [...prev, c]);
    window.setTimeout(() => {
      setSparks((prev) => prev.filter((s) => s.id !== c.id));
    }, 540);
  }, []);

  const stageRef = useClinkPhysics(reduced, onClink);

  return (
    <section
      className="ns-clink"
      aria-labelledby="ns-clink-title"
      data-reveal="panel"
    >
      <div className="ns-clink__intro">
        <p className="ns-eyebrow" data-reveal>
          <span lang="ko">03화 · 건배</span>
          <span>CH. 03 — TOUCHING GLASSES</span>
        </p>
        <h2 className="ns-sechead" id="ns-clink-title" data-reveal>
          <span className="ns-sechead__ko" lang="ko">
            잔을 끌어서 부딪쳐 보세요
          </span>
          <span className="ns-sechead__en">Drag a glass. Clink it.</span>
        </h2>
        <p data-reveal>
          <span lang="ko">
            잔을 끌어 던지면 관성을 타고, 제자리로 스프링처럼 돌아온다. 두 잔이
            닿으면 짠! — 포장마차의 한밤중 건배.
          </span>
          Fling a glass and it coasts on inertia, then springs back home. When
          two touch, they clink — the midnight toast of the tent.
        </p>
      </div>

      <div className="ns-clink__table" ref={stageRef}>
        <p className="ns-clink__cap">
          <span lang="ko">마우스로 끌기 · 잔을 부딪치면 짠!</span>
          <span>DRAG · CLINK = 짠!</span>
        </p>

        {BODIES.map((b) => (
          <div
            key={b.key}
            className={
              b.kind === "glass"
                ? "ns-clink-body"
                : "ns-clink-body ns-skewer-body"
            }
            data-clink
            data-rest-x={b.restX}
            data-rest-y={b.restY}
            data-clink-r={b.r}
            role="button"
            tabIndex={0}
            aria-label={b.label}
            aria-grabbed="false"
            style={
              { transform: `translate3d(${b.restX}px, ${b.restY}px, 0)` } as CSSProperties
            }
          >
            {b.kind === "glass" ? (
              <span className="ns-glass" aria-hidden="true">
                <span className="ns-glass__bottle" />
                <span className="ns-glass__cup" />
              </span>
            ) : (
              <span aria-hidden="true">
                <span className="ns-skewer-body__stick" />
                <span
                  className="ns-skewer-body__chunk"
                  style={{ left: "20%" }}
                />
                <span
                  className="ns-skewer-body__chunk"
                  style={{ left: "45%" }}
                />
                <span
                  className="ns-skewer-body__chunk"
                  style={{ left: "70%" }}
                />
                <span
                  className="ns-skewer-body__chunk"
                  style={{ left: "90%" }}
                />
              </span>
            )}
          </div>
        ))}

        {/* Clink sparks — positioned at the clink midpoint, auto-clear. */}
        {sparks.map((s, i) => (
          <span
            key={s.id}
            className="ns-spark"
            aria-hidden="true"
            style={{ left: `${s.x}px`, top: `${s.y}px`, zIndex: 6 + i }}
          >
            <span className="ns-spark__sfx" lang="ko">
              {CLINK_SFX[s.id % CLINK_SFX.length]}
            </span>
          </span>
        ))}
      </div>

      <p className="ns-cook__hint" style={{ marginTop: "1.2rem" }}>
        <span lang="ko">권장: 마우스 / 트랙패드</span>
        <span className="ns-mono">FINE POINTER RECOMMENDED · TOUCH = STILL LIFE</span>
      </p>
    </section>
  );
}

"use client";

/**
 * Chapter 05 — the menu. 오늘의 메뉴 / TODAY'S MENU. Plain semantic HTML: an
 * ordered list of dishes, each a row with a number, a bilingual name, a
 * price, and an optional tag (매운 / NEW). Fully readable with JS off — this
 * is the SSR-completed page, and nothing here is gated behind `.ns-js` or any
 * observer. The menu is the part of the tent that has to survive a blackout.
 *
 * Prices are tabular-nums mono so the column lines up; the tag chips reuse the
 * page's neon palette (soju-green for vegetarian, pink for hot). The dashed
 * row dividers read as a hand-torn receipt.
 */
type Dish = {
  no: string;
  ko: string;
  en: string;
  price: string;
  tag?: { ko: string; en: string; kind: "hot" | "veg" };
};

const DISHES: Dish[] = [
  {
    no: "01",
    ko: "닭꼬치",
    en: "Grilled chicken skewer",
    price: "₩3,500",
    tag: { ko: "시그니처", en: "SIGNATURE", kind: "hot" },
  },
  {
    no: "02",
    ko: "떡·소시지 꼬치",
    en: "Tteokbokki & sausage skewer",
    price: "₩4,000",
    tag: { ko: "매운맛", en: "SPICY", kind: "hot" },
  },
  {
    no: "03",
    ko: "오뎅 탕",
    en: "Odeng (fish-cake) soup",
    price: "₩5,000",
    tag: { ko: "국물", en: "BROTH", kind: "veg" },
  },
  {
    no: "04",
    ko: "골뱅이 비빔면",
    en: "Spicy cone-nail noodles",
    price: "₩7,000",
    tag: { ko: "매운맛", en: "SPICY", kind: "hot" },
  },
  {
    no: "05",
    ko: "파전",
    en: "Green-onion pancake",
    price: "₩8,000",
    tag: { ko: "채소", en: "VEG", kind: "veg" },
  },
  {
    no: "06",
    ko: "소주 한 병",
    en: "Soju, one bottle",
    price: "₩5,500",
  },
  {
    no: "07",
    ko: "맥주 500mL",
    en: "Draft beer, 500mL",
    price: "₩4,500",
  },
];

export default function MenuBoard() {
  return (
    <section
      className="ns-menu"
      aria-labelledby="ns-menu-title"
      data-reveal="panel"
    >
      <div className="ns-menu__inner">
        <div className="ns-menu__head">
          <h2
            className="ns-menu__title"
            id="ns-menu-title"
            lang="ko"
            data-reveal
          >
            오늘의 메뉴
          </h2>
          <p className="ns-menu__date ns-mono" data-reveal>
            2026.07.18 · FRI · 밤 9시 — 새벽 4시
          </p>
        </div>

        <ol className="ns-menu__list">
          {DISHES.map((d) => (
            <li className="ns-menu__row" key={d.no} data-reveal>
              <span className="ns-menu__no ns-mono">{d.no}</span>
              <span className="ns-menu__name">
                <span lang="ko">{d.ko}</span>
                <span className="ns-menu__name-en">{d.en}</span>
              </span>
              <span className="ns-menu__price">
                {d.price}
                {d.tag ? (
                  <span
                    className={
                      d.tag.kind === "hot"
                        ? "ns-menu__tag ns-menu__tag--hot"
                        : "ns-menu__tag"
                    }
                  >
                    <span lang="ko">{d.tag.ko}</span>{" "}
                    <span className="ns-mono">{d.tag.en}</span>
                  </span>
                ) : null}
              </span>
            </li>
          ))}
        </ol>

        <p className="ns-menu__note" data-reveal>
          <span lang="ko">
            모든 가격 부가세 포함. 매운맛 조절 가능합니다 — 사장님께 말씀만
            주세요. 자리는 공유합니다, 모르는 분 옆에 앉는 게 이곳의 예의.
          </span>
          All prices include tax. Spice is adjustable — just ask the boss. Seats
          are shared; sitting beside a stranger is the courtesy of this place.
        </p>
      </div>
    </section>
  );
}

"use client";

import { type CSSProperties } from "react";
import { useNeonFlicker } from "../hooks/useNeonFlicker";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";

/**
 * Chapter 04 — the ASCII neon signboard. The `ascii-render` technique. Three
 * neon signs are rendered as ASCII-art character fields: the glyphs are laid
 * out in a monospace grid (Space Mono) so the density of characters forms a
 * picture — a soju bottle, a fish (오뎅), a bowl rising with steam. Each
 * non-space glyph is its own cell (`.ns-ascii__c`) carrying a neon glow via
 * `text-shadow`; `useNeonFlicker` periodically dims a small random subset of
 * cells so the sign reads as a bank of dying bulbs, not a printed string.
 *
 * Three signs, three neon colors (amber / pink / green), three mutually-prime
 * flicker periods — the buzz of overworked tent bulbs.
 *
 * Under reduced motion the hook never attaches; styles.css holds every sign
 * at full, steady brightness. Without JS the signs are fully lit from the
 * first paint (the `is-dim` class is only ever added by JS, and the pre-state
 * for `[data-reveal]` is gated behind `.ns-js`). The ASCII is also plain text
 * inside a `<pre>`, so it is fully readable and copy-pasteable with JS off.
 *
 * The ASCII strings are written by hand here (in-component) so they ship as
 * real text — no canvas rasterization, no image. Each glyph is wrapped so the
 * flicker hook can address it; spaces become invisible cells so the grid
 * stays intact.
 */

/* The three ASCII signs. Each line is the same width; spaces are part of the
   picture. Hand-tuned to read at a glance at ~10–13px monospace. */
const SIGN_AMBER = [
  "       ___       ",
  "      |   |      ",
  "      |   |      ",
  "      |___|      ",
  "      |   |      ",
  "      |   |      ",
  "     /|   |\\     ",
  "    / |___| \\    ",
  "   /  |   |  \\   ",
  "  /   |   |   \\  ",
  "  ~~~~~~~~~~~~~  ",
  "   HOT  OFF  THE ",
  "     GRILL ·     ",
];

const SIGN_PINK = [
  "     .----.      ",
  "    /      \\     ",
  "   |  ()()  |    ",
  "   |  ()()  |    ",
  "    \\      /     ",
  "     '----'      ",
  "       |         ",
  "       |         ",
  "       |         ",
  "   ~~~~~~~~~~    ",
  "   COLD DRINKS   ",
  "   시원한 음료    ",
];

const SIGN_GREEN = [
  "         w        ",
  "        / \\       ",
  "       /   \\      ",
  "      / o   \\     ",
  "     /       \\    ",
  "    /         \\   ",
  "    \\         /   ",
  "     \\~~~~~~~/    ",
  "      \\~~~~~/     ",
  "       ~~~~~      ",
  "   FRESH ODENG    ",
  "   따끈 오뎅       ",
];

const SIGNS = [
  {
    key: "amber",
    cls: "ns-ascii--amber",
    art: SIGN_AMBER,
    head: { ko: "간판 01 · 불 앞", en: "SIGN 01 — GRILL" },
    caption: {
      ko: "치치칵! 소리와 함께 올라오는 한 꼬치.",
      en: "A skewer straight off the sizzle.",
    },
  },
  {
    key: "pink",
    cls: "ns-ascii--pink",
    art: SIGN_PINK,
    head: { ko: "간판 02 · 차가운 표", en: "SIGN 02 — COLD CASE" },
    caption: {
      ko: "얼음 서리가 앉은 차가운 한 잔.",
      en: "A cold glass, frost still on it.",
    },
  },
  {
    key: "green",
    cls: "ns-ascii--green",
    art: SIGN_GREEN,
    head: { ko: "간판 03 · 김 오르는 가마", en: "SIGN 03 — STEAM POT" },
    caption: {
      ko: "국물이 끓어오르는 따끈한 오뎅.",
      en: "Odeng out of the still-bubbling broth.",
    },
  },
] as const;

/** Split an ASCII string into per-glyph cells so the flicker hook can dim
 *  individual "bulbs". Spaces stay in-grid as invisible cells. */
function cellsFor(line: string) {
  return Array.from(line).map((ch, i) => ({
    key: i,
    char: ch,
    space: ch === " ",
  }));
}

export default function NeonSigns() {
  const reduced = usePrefersReducedMotion();

  return (
    <section
      className="ns-signs"
      aria-labelledby="ns-signs-title"
      data-reveal="panel"
    >
      <div className="ns-signs__intro">
        <p className="ns-eyebrow" data-reveal>
          <span lang="ko">04화 · 네온 간판</span>
          <span>CH. 04 — NEON SIGNS</span>
        </p>
        <h2 className="ns-sechead" id="ns-signs-title" data-reveal>
          <span className="ns-sechead__ko" lang="ko">
            글자로 그린 네온
          </span>
          <span className="ns-sechead__en">Neon, drawn in characters</span>
        </h2>
        <p data-reveal>
          <span lang="ko">
            네온 사인 세 개. 그림이 아니라 글자다 — 모노스페이스 격자에 글자
            밀도로 그린 그림. 한 글자가 한 전구이고, 몇 전구는 품이 다해
            깜빡인다.
          </span>
          Three neon signs — not pictures but text, a picture made of character
          density on a monospace grid. Each glyph is a bulb, and a few bulbs
          flicker because they are tired.
        </p>
      </div>

      <div className="ns-signs__grid">
        {SIGNS.map((sign) => (
          <SignCard key={sign.key} sign={sign} reduced={reduced} />
        ))}
      </div>
    </section>
  );
}

/** One sign card. Splits the art into cells and wires the flicker hook. */
function SignCard({
  sign,
  reduced,
}: {
  sign: (typeof SIGNS)[number];
  reduced: boolean;
}) {
  const ref = useNeonFlicker<HTMLPreElement>(reduced);
  return (
    <article className={`ns-ascii ${sign.cls}`} data-reveal>
      <p className="ns-ascii__head">
        <span lang="ko">{sign.head.ko}</span>
        <span className="ns-mono">· {sign.head.en}</span>
      </p>
      <pre className="ns-ascii__pre" ref={ref} aria-hidden="true">
        {sign.art.map((line, li) => (
          <span key={li} style={{ display: "block" }}>
            {cellsFor(line).map((c) => (
              <span
                key={c.key}
                className={`ns-ascii__c${c.space ? " is-space" : ""}`}
              >
                {c.space ? "\u00A0" : c.char}
              </span>
            ))}
          </span>
        ))}
      </pre>
      <p className="ns-ascii__caption" style={{ "--ns-c": 0 } as CSSProperties}>
        <span lang="ko">{sign.caption.ko}</span>
        <span>{sign.caption.en}</span>
      </p>
    </article>
  );
}

"use client";

import { type CSSProperties } from "react";
import { useSpriteScrub } from "../hooks/useSpriteScrub";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";

/**
 * Chapter 02 — the cooking sprite sequence. The `sprite-scrub` technique,
 * with code-drawn sprites instead of an image strip (this is a `media.source:
 * "code"` entry). A stack of frames — each a pure CSS drawing of the steam
 * plume + halftone-dot heat field at a different phase of cooking — sits
 * inside a pinned-tall stage; as you scroll through the stage, `useSpriteScrub`
 * writes `--ns-steam` ∈ [0,1] and styles.css maps that to each frame's
 * opacity (a triangular window per frame, so only ~3 are ever meaningfully
 * visible — a crossfade, not a flip).
 *
 * Six frames: raw (no steam) → warming (faint plume, sparse dots) → searing
 * (tall plume, dense dots, 치치칵! SFX) → cooking → almost-done → plated
 * (food darker via per-frame filter, plume settling, 냠냠! SFX). Each frame
 * carries its own `--ns-c` (center, where it peaks) and `--ns-h`
 * (half-window). The opacity math lives in styles.css.
 *
 * Under reduced motion the hook never attaches; styles.css pins `--ns-steam`
 * at 1 (the plated/cooked end state), so the final frame is fully visible and
 * the food is done. Without JS, `--ns-steam` stays at its declared 0 (raw),
 * which is also a legitimate, readable frame — the grill is on, the food is
 * going on.
 *
 * The scrub rail on the right is the page's honesty: this is scrubbed by your
 * scroll, not by a timer.
 */
const FRAMES = [
  {
    c: 0.0,
    h: 0.18,
    phase: { ko: "01 · 생고기", en: "RAW" },
    sfx: "",
    plume: { opacity: 0, scale: 0.6 },
    dotSize: 1,
    dotOpacity: 0.08,
  },
  {
    c: 0.2,
    h: 0.16,
    phase: { ko: "02 · 불 올라간다", en: "FIRE ON" },
    sfx: "",
    plume: { opacity: 0.4, scale: 0.75 },
    dotSize: 1.2,
    dotOpacity: 0.18,
  },
  {
    c: 0.4,
    h: 0.15,
    phase: { ko: "03 · 지지는 소리", en: "SEARING" },
    sfx: "치치칵!",
    plume: { opacity: 0.85, scale: 1 },
    dotSize: 1.6,
    dotOpacity: 0.34,
  },
  {
    c: 0.6,
    h: 0.15,
    phase: { ko: "04 · 굽는 중", en: "COOKING" },
    sfx: "츄아아—",
    plume: { opacity: 0.9, scale: 1.1 },
    dotSize: 1.8,
    dotOpacity: 0.4,
  },
  {
    c: 0.8,
    h: 0.15,
    phase: { ko: "05 · 다 됐다", en: "ALMOST DONE" },
    sfx: "",
    plume: { opacity: 0.6, scale: 1.05 },
    dotSize: 1.5,
    dotOpacity: 0.28,
  },
  {
    c: 1.0,
    h: 0.18,
    phase: { ko: "06 · 한 접시 · 나왔습니다", en: "PLATED" },
    sfx: "냠냠!",
    plume: { opacity: 0.3, scale: 0.9 },
    dotSize: 1.2,
    dotOpacity: 0.16,
  },
] as const;

export default function SteamScrub() {
  const reduced = usePrefersReducedMotion();
  const stageRef = useSpriteScrub<HTMLDivElement>(reduced);

  return (
    <section
      className="ns-cook"
      aria-labelledby="ns-cook-title"
      data-reveal="panel"
    >
      <div className="ns-cook__intro">
        <p className="ns-eyebrow" data-reveal>
          <span lang="ko">02화 · 불 앞에서</span>
          <span>CH. 02 — AT THE GRILL</span>
        </p>
        <h2 className="ns-sechead" id="ns-cook-title" data-reveal>
          <span className="ns-sechead__ko" lang="ko">
            스크롤하면 익어간다
          </span>
          <span className="ns-sechead__en">Scroll to cook the skewer</span>
        </h2>
        <p data-reveal>
          <span lang="ko">
            한 꼬치가 불에 올라가 한 접시가 되기까지, 여섯 장면. 스크롤이 곧
            시간이다 — 비디오가 아니라, 코드로 그린 스프라이트 여섯 장을 당신의
            스크롤이 스크럽한다.
          </span>
          Six frames from skewer-on-the-grill to a plated dish. The scroll is
          the timeline — no video, just six code-drawn sprite frames your scroll
          scrubs through.
        </p>
      </div>

      <div className="ns-cook__stage" ref={stageRef}>
        {/* the grill + skewers — present in every frame, the anchor */}
        <div className="ns-cook__grill" aria-hidden="true" />
        <div className="ns-cook__skewer" aria-hidden="true" />
        <div className="ns-cook__skewer ns-cook__skewer--2" aria-hidden="true" />
        <div className="ns-cook__skewer ns-cook__skewer--3" aria-hidden="true" />

        {/* the sprite frames — each a CSS steam plume + halftone heat field.
            opacity is driven by --ns-steam via the per-frame --ns-c / --ns-h. */}
        {FRAMES.map((f, i) => (
          <div
            key={i}
            className="ns-cook__frame"
            aria-hidden="true"
            style={
              {
                "--ns-c": f.c,
                "--ns-h": f.h,
              } as CSSProperties
            }
          >
            <div
              className="ns-cook__plume"
              style={{
                opacity: f.plume.opacity,
                transform: `translateX(-50%) scale(${f.plume.scale})`,
              }}
            />
            <div
              className="ns-cook__heat"
              style={{
                backgroundSize: `${14 / f.dotSize}px ${14 / f.dotSize}px`,
                opacity: f.dotOpacity,
              }}
            />
          </div>
        ))}

        {/* the per-frame phase labels + SFX, same opacity math */}
        <div className="ns-cook__labels">
          {FRAMES.map((f, i) =>
            f.phase.en ? (
              <p
                key={i}
                className="ns-cook__label ns-cook__phase"
                style={
                  {
                    "--ns-c": f.c,
                    "--ns-h": f.h,
                  } as CSSProperties
                }
              >
                <span lang="ko">{f.phase.ko}</span>{" "}
                <span className="ns-mono">· {f.phase.en}</span>
              </p>
            ) : null,
          )}
        </div>
        {FRAMES.map((f, i) =>
          f.sfx ? (
            <div
              key={i}
              className="ns-cook__sfx"
              lang="ko"
              style={
                {
                  "--ns-c": f.c,
                  "--ns-h": f.h,
                } as CSSProperties
              }
            >
              {f.sfx}
            </div>
          ) : null,
        )}

        {/* the honesty rail: a vertical progress bar = how cooked */}
        <div className="ns-cook__rail" aria-hidden="true">
          <div className="ns-cook__rail-fill" />
        </div>
      </div>

      <p className="ns-cook__hint">
        <span lang="ko">스크롤이 익힌다</span>
        <span className="ns-mono">SCROLL = COOK · 0% RAW → 100% PLATED</span>
      </p>
    </section>
  );
}

"use client";

import { useEffect, useRef } from "react";

export type Clink = {
  /** x of the clink in the shared stage's local px space (for the spark) */
  x: number;
  /** y of the clink in the shared stage's local px space (for the spark) */
  y: number;
  /** monotonic id so React keys + a cleanup timer can find it */
  id: number;
};

type Body = {
  el: HTMLElement;
  x: number;
  y: number;
  vx: number;
  vy: number;
  /** rest position in local px */
  restX: number;
  restY: number;
  /** radius for overlap/clink detection, in px */
  r: number;
  dragging: boolean;
};

type Pointer = {
  id: number;
  body: Body | null;
  /** last pointer pos in local px, for velocity sampling */
  px: number;
  py: number;
};

/**
 * Drag physics — the `drag-physics` technique. Powers the soju glasses and
 * skewers you can drag around the table and "clink". Several draggable bodies
 * share one stage; each carries its own rest position, and on release it
 * coasts on inertia (velocity captured from the last pointer move) then
 * springs back home. When two bodies' circles overlap, a *clink* fires — a
 * callback hands the clink coordinate to React so a spark SFX can render, and
 * the two bodies get a small knockback impulse so the clink feels physical
 * instead of pass-through.
 *
 * Physics, tuned by hand:
 *  - velocity decay 0.86/frame (coast dies in ~half a second)
 *  - spring stiffness 0.18, damping 0.78 (overshoots just once, then settles)
 *  - clink knockback: each body takes the unit vector away from the other ×
 *    a fixed impulse (6 px/frame), applied to velocity, so a hard drag-in
 *    clinks harder than a graze
 *
 * The loop runs a single rAF for the whole stage, writing `transform:
 * translate3d()` per body (transform-only — never layout). It parks itself
 * when every body is at rest and un-dragged, so an idle table costs zero
 * frames. It pauses on `visibilitychange` (hidden) and never runs under
 * reduced motion or on coarse pointers — under either, the glasses sit at
 * rest and the clink is a no-op (touch users still see the full table; the
 * drag is a flourish, not a gate).
 *
 * `onClink` is called from inside rAF; React state updates are batched and
 * fine here because clinks are rare (a few per session). The hook owns no
 * state itself — it returns a ref to attach to the stage element and expects
 * every `[data-clink]` child to expose its rest position via `data-rest-x` /
 * `data-rest-y` (in px, local to the stage) at mount.
 */
export function useClinkPhysics(
  disabled: boolean,
  onClink: (c: Clink) => void,
) {
  const stageRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const stage = stageRef.current;
    if (!stage || disabled) return;
    if (!window.matchMedia("(pointer: fine)").matches) return;

    const bodies: Body[] = [];
    const pointers = new Map<number, Pointer>();
    let raf = 0;
    let running = false;
    let clinkId = 0;
    // Debounce clinks: the same pair can't clink again within this many ms.
    let lastClinkAt = 0;

    // Snapshot every draggable child. Rest positions are read from data attrs
    // so the markup stays declarative and survives re-render.
    const nodes = Array.from(
      stage.querySelectorAll<HTMLElement>("[data-clink]"),
    );
    for (const el of nodes) {
      const restX = Number(el.dataset.restX ?? 0);
      const restY = Number(el.dataset.restY ?? 0);
      const r = Number(el.dataset.clinkR ?? 28);
      const body: Body = {
        el,
        x: restX,
        y: restY,
        vx: 0,
        vy: 0,
        restX,
        restY,
        r,
        dragging: false,
      };
      bodies.push(body);
      el.style.transform = `translate3d(${restX}px, ${restY}px, 0)`;
    }
    if (bodies.length < 2) return;

    const write = (b: Body) => {
      b.el.style.transform = `translate3d(${b.x}px, ${b.y}px, 0)`;
    };

    const stageRect = () => stage.getBoundingClientRect();

    const localPoint = (clientX: number, clientY: number) => {
      const r = stageRect();
      return { x: clientX - r.left, y: clientY - r.top };
    };

    const hit = (lx: number, ly: number): Body | null => {
      // Topmost-first (last in DOM paints on top).
      for (let i = bodies.length - 1; i >= 0; i--) {
        const b = bodies[i];
        const dx = lx - b.x;
        const dy = ly - b.y;
        if (dx * dx + dy * dy <= b.r * b.r) return b;
      }
      return null;
    };

    const onDown = (e: PointerEvent) => {
      if (e.button !== undefined && e.button !== 0) return;
      const p = localPoint(e.clientX, e.clientY);
      const body = hit(p.x, p.y);
      if (!body) return;
      body.dragging = true;
      body.vx = 0;
      body.vy = 0;
      pointers.set(e.pointerId, {
        id: e.pointerId,
        body,
        px: p.x,
        py: p.y,
      });
      stage.setPointerCapture(e.pointerId);
      body.el.classList.add("is-grabbed");
      wake();
    };

    const onMove = (e: PointerEvent) => {
      const ptr = pointers.get(e.pointerId);
      if (!ptr || !ptr.body) return;
      const p = localPoint(e.clientX, e.clientY);
      const b = ptr.body;
      // Velocity from the last move, smoothed so a single jump doesn't fling.
      b.vx = (b.vx + (p.x - ptr.px)) * 0.5;
      b.vy = (b.vy + (p.y - ptr.py)) * 0.5;
      b.x = p.x;
      b.y = p.y;
      ptr.px = p.x;
      ptr.py = p.y;
      write(b);
    };

    const onUp = (e: PointerEvent) => {
      const ptr = pointers.get(e.pointerId);
      if (!ptr) return;
      if (ptr.body) {
        ptr.body.dragging = false;
        ptr.body.el.classList.remove("is-grabbed");
      }
      pointers.delete(e.pointerId);
      try {
        stage.releasePointerCapture(e.pointerId);
      } catch {
        /* pointer capture may already be gone */
      }
      wake();
    };

    const tryClink = (a: Body, b: Body) => {
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const dist = Math.hypot(dx, dy);
      const reach = a.r + b.r;
      if (dist >= reach) return false;
      const now = performance.now();
      if (now - lastClinkAt < 180) return false;
      lastClinkAt = now;
      // Clack: midpoint between the two, in stage-local px.
      const cx = (a.x + b.x) / 2;
      const cy = (a.y + b.y) / 2;
      // Knockback away from each other.
      const nx = dx / (dist || 1);
      const ny = dy / (dist || 1);
      const impulse = 6;
      if (!a.dragging) {
        a.vx -= nx * impulse;
        a.vy -= ny * impulse;
      }
      if (!b.dragging) {
        b.vx += nx * impulse;
        b.vy += ny * impulse;
      }
      clinkId += 1;
      onClink({ x: cx, y: cy, id: clinkId });
      return true;
    };

    const step = () => {
      running = true;
      // Integrate. Velocity decay, then spring toward rest, then position.
      let active = false;
      // Clink check across all pairs (n is tiny — 2–4 glasses).
      for (let i = 0; i < bodies.length; i++) {
        for (let j = i + 1; j < bodies.length; j++) {
          tryClink(bodies[i], bodies[j]);
        }
      }
      for (const b of bodies) {
        if (b.dragging) {
          active = true;
          continue;
        }
        // Decay (coast).
        b.vx *= 0.86;
        b.vy *= 0.86;
        // Spring toward rest.
        const sx = (b.restX - b.x) * 0.18;
        const sy = (b.restY - b.y) * 0.18;
        b.vx = (b.vx + sx) * 0.78 + sx * 0.22;
        b.vy = (b.vy + sy) * 0.78 + sy * 0.22;
        b.x += b.vx;
        b.y += b.vy;
        // Settle threshold — stop writing when sub-pixel.
        const moving =
          Math.abs(b.vx) > 0.05 ||
          Math.abs(b.vy) > 0.05 ||
          Math.abs(b.restX - b.x) > 0.2 ||
          Math.abs(b.restY - b.y) > 0.2;
        if (moving) active = true;
        write(b);
      }
      if (active) {
        raf = window.requestAnimationFrame(step);
      } else {
        running = false;
      }
    };

    const wake = () => {
      if (running) return;
      running = true;
      raf = window.requestAnimationFrame(step);
    };

    const onVisibility = () => {
      if (document.hidden) {
        if (raf) window.cancelAnimationFrame(raf);
        running = false;
      }
    };

    stage.addEventListener("pointerdown", onDown);
    stage.addEventListener("pointermove", onMove);
    stage.addEventListener("pointerup", onUp);
    stage.addEventListener("pointercancel", onUp);
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stage.removeEventListener("pointerdown", onDown);
      stage.removeEventListener("pointermove", onMove);
      stage.removeEventListener("pointerup", onUp);
      stage.removeEventListener("pointercancel", onUp);
      document.removeEventListener("visibilitychange", onVisibility);
      if (raf) window.cancelAnimationFrame(raf);
      for (const b of bodies) {
        b.el.style.transform = "";
        b.el.classList.remove("is-grabbed");
      }
    };
  }, [disabled, onClink]);

  return stageRef;
}

"use client";

import { useEffect, useState } from "react";

/**
 * Tracks whether a given element is currently in the viewport, plus a latched
 * `seen` flag (true once the element has ever been in view). The consumer
 * owns the ref (created with `useRef`) and passes it in — this keeps the ref
 * object stable across renders and side-steps the strict react-hooks/refs
 * lint rule that flags refs returned from custom hooks.
 *
 * `once` defaults to true — most reveals are one-shot.
 */
export function useInView<T extends HTMLElement>(
  targetRef: React.RefObject<T | null>,
  options?: { threshold?: number; rootMargin?: string; once?: boolean },
): { inView: boolean; seen: boolean } {
  const threshold = options?.threshold ?? 0.4;
  const rootMargin = options?.rootMargin ?? "0px 0px -10% 0px";
  const once = options?.once ?? true;

  const [inView, setInView] = useState(false);
  const [seen, setSeen] = useState(false);

  useEffect(() => {
    const el = targetRef.current;
    if (!el || !("IntersectionObserver" in window)) {
      setInView(true);
      setSeen(true);
      return;
    }
    const io = new IntersectionObserver(
      (hits) => {
        for (const hit of hits) {
          setInView(hit.isIntersecting);
          if (hit.isIntersecting) {
            setSeen(true);
            if (once) {
              io.disconnect();
              return;
            }
          }
        }
      },
      { threshold, rootMargin },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [targetRef, threshold, rootMargin, once]);

  return { inView, seen };
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Neon flicker for the ASCII-art signs — the on-screen half of the
 * `ascii-render` technique (the other half is rendering the sign as a
 * character density field at all). The ASCII sign is a monospace grid of
 * glyphs; this hook periodically dims a small random subset of cells so the
 * sign reads as a bank of dying bulbs, not a printed string.
 *
 * The hook owns no React state. It attaches to the sign's container, finds
 * every `.ns-ascii__c` cell inside, and on a timer re-rolls a ~8% sample to
 * `is-dim` (opacity set by CSS, never inline color). Two signs can share one
 * hook because each carries its own `data-neon-seed`; the timers are offset
 * so they never sync.
 *
 * Under reduced motion the hook does nothing — styles.css holds every sign at
 * full, steady brightness. The hook also pauses when the sign is offscreen
 * (IntersectionObserver) and on hidden tabs, so an unseen sign costs nothing.
 *
 * `periodMs` defaults to 220ms — fast enough to read as a flicker, slow
 * enough that the eye can latch a sign and read it. `dimRatio` defaults to
 * 0.08 (≈8% of cells dim each roll).
 */
export function useNeonFlicker<T extends HTMLElement>(
  disabled: boolean,
  periodMs = 220,
  dimRatio = 0.08,
) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;

    const cells = Array.from(
      el.querySelectorAll<HTMLElement>(".ns-ascii__c"),
    );
    if (cells.length === 0) return;

    let inView = true;
    let io: IntersectionObserver | null = null;

    const roll = () => {
      if (!inView || document.hidden) return;
      // Clear a fraction, dim a fraction. Bounded work — n is small (~200).
      for (const c of cells) c.classList.remove("is-dim");
      const n = Math.max(1, Math.floor(cells.length * dimRatio));
      for (let k = 0; k < n; k++) {
        const idx = Math.floor(Math.random() * cells.length);
        cells[idx].classList.add("is-dim");
      }
    };

    const timer: number | undefined = window.setInterval(roll, periodMs);

    if ("IntersectionObserver" in window) {
      io = new IntersectionObserver(
        (hits) => {
          for (const h of hits) {
            inView = h.isIntersecting;
            if (!inView) {
              // Park the sign lit when it leaves view.
              for (const c of cells) c.classList.remove("is-dim");
            }
          }
        },
        { threshold: 0.05 },
      );
      io.observe(el);
    }

    return () => {
      if (timer !== undefined) window.clearInterval(timer);
      io?.disconnect();
      for (const c of cells) c.classList.remove("is-dim");
    };
  }, [disabled, periodMs, dimRatio]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport, by
 * adding an `is-visible` class. The pre-reveal state lives in styles.css and
 * is gated behind the `.ns-js` root class — so with JavaScript off, every word
 * and every panel is plainly visible. The tent is open either way; you just
 * walk in.
 *
 * Two flavors, mirroring the webtoon's two kinds of beat:
 *   data-reveal          — the element itself fades and rises (650ms), with a
 *                          70ms stagger between elements of the same observer
 *                          batch, so a screenful never moves as one slab.
 *   data-reveal="panel"  — a panel container; it does not animate itself, it
 *                          only receives `is-visible` so its own inner
 *                          choreography (steam scrub, neon flicker, clink
 *                          activation) can begin.
 */
export function useReveal<T extends HTMLElement>(disabled: boolean) {
  const rootRef = useRef<T | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (disabled || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          if (el.dataset.reveal !== "panel") {
            el.style.transitionDelay = `${batch * 70}ms`;
            batch += 1;
          }
          el.classList.add("is-visible");
          io.unobserve(el);
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [disabled]);

  return rootRef;
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Sprite-sequence scrub — the `sprite-scrub` technique, here applied to a
 * *code-drawn* sprite strip (no image payload). The cooking panel has a stack
 * of frames — steam plume positions + halftone-dot densities, each a pure
 * CSS/SVG drawing — and this hook scrubs which frame is showing by writing a
 * single number `--ns-steam` ∈ [0, 1] onto the panel as you scroll through it.
 *
 * The frames themselves live in the component as siblings; styles.css maps
 * `--ns-steam` to each frame's opacity so only ~3 are ever meaningfully
 * visible (a crossfade, not a flip). The hook never touches a frame directly —
 * it only writes the scrub variable, transform/opacity-safe.
 *
 * Mechanically: a scroll listener (passive) computes how far the panel has
 * traveled through the viewport — 0 when its top hits the bottom of the
 * screen, 1 when its bottom hits the top — and writes that onto the element as
 * `--ns-steam`. A rAF coalesces multiple scroll events into one write and
 * clamps `dt` to 48ms so a backgrounded tab cannot lurch on return. The loop
 * pauses entirely on `visibilitychange` (hidden) and never runs under reduced
 * motion — under reduced motion styles.css pins `--ns-steam` at its final
 * frame (steam fully risen, food plated).
 *
 * `targetRef` should be the element whose travel drives the scrub; the
 * consumer owns the ref. `once` is unused here (scrub is reversible by
 * nature) — kept off to match the gallery's hook ergonomics.
 */
export function useSpriteScrub<T extends HTMLElement>(disabled: boolean) {
  const targetRef = useRef<T | null>(null);

  useEffect(() => {
    const el = targetRef.current;
    if (!el || disabled) return;

    let raf = 0;
    let running = false;

    const compute = () => {
      const rect = el.getBoundingClientRect();
      const vh = window.innerHeight;
      // 0 when the panel's top is at the bottom of the viewport; 1 when its
      // bottom is at the top. Clamp so the scrub holds at both ends.
      const top = rect.top;
      const bottom = rect.bottom;
      const span = vh + rect.height;
      const traveled = vh - top; // how far the panel's top has risen into view
      const p = (traveled / span) * 1;
      const clamped = Math.min(Math.max(p, 0), 1);
      el.style.setProperty("--ns-steam", clamped.toFixed(4));
      // Suppress the unused `bottom` read warning — kept for clarity of the
      // span math; the optimizer drops it.
      void bottom;
    };

    const wake = () => {
      if (running) return;
      running = true;
      raf = window.requestAnimationFrame(() => {
        running = false;
        compute();
      });
    };

    const onVisibility = () => {
      if (document.hidden) {
        if (raf) window.cancelAnimationFrame(raf);
        running = false;
      } else {
        wake();
      }
    };

    compute();
    window.addEventListener("scroll", wake, { passive: true });
    window.addEventListener("resize", wake, { passive: true });
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      if (raf) window.cancelAnimationFrame(raf);
      window.removeEventListener("scroll", wake);
      window.removeEventListener("resize", wake);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--ns-steam");
    };
  }, [disabled]);

  return targetRef;
}

"use client";

import { useEffect, useRef } from "react";
import "./styles.css";
import { blackHanSans, gaegu, notoSansKR, spaceMono } from "./fonts";
import Hero from "./components/Hero";
import SteamScrub from "./components/SteamScrub";
import ClinkDrag from "./components/ClinkDrag";
import NeonSigns from "./components/NeonSigns";
import MenuBoard from "./components/MenuBoard";
import NightFooter from "./components/NightFooter";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useReveal } from "./hooks/useReveal";

/**
 * NIGHT-SNACK — 새벽 한 시의 포장마차, the third webtoon twin. Where PPANG!
 * is a cozy dawn bakery (warm cream paper, brown ink, generated art) and
 * MOONLIT is a lonely delivery ride (cold indigo night, generated art),
 * NIGHT-SNACK is the vibrant, crowded, steamy chaos of a pojangmacha street-
 * food tent at 1 AM — neon, steam, soju, laughter, skewers. Energetic and
 * social, not lonely or cozy.
 *
 * The foreground is PURE CODE (CSS/SVG webtoon shapes) — unlike ppang/moonlit
 * which ship ComfyUI illustrations as the subject. NIGHT-SNACK keeps its
 * signature CSS/SVG illustration (flat shapes, halftone dots, speech-bubble
 * SFX, neon glow) in the foreground, with one generated alley photo drifting
 * blurred behind the hero as the back-alley atmosphere. `media.source:
 * "hybrid"`.
 *
 * Three techniques, all earned on screen, all DIFFERENT from ppang's
 * (clip-path-reveal / char-split-reveal / pointer-parallax) and moonlit's
 * (typewriter / svg-line-draw / marquee):
 *  - sprite-scrub — a steam/halftone sprite sequence scrubbed by scroll (the
 *    food cooking), six code-drawn frames whose opacity is driven by
 *    `--ns-steam`.
 *  - drag-physics — draggable soju glasses / skewers you can "clink"; inertia
 *    + spring back, overlap detection fires a spark SFX.
 *  - ascii-render — three neon signs rendered as ASCII-art character fields
 *    that flicker per-glyph, each glyph a dying bulb.
 *
 * `.ns-js` is added imperatively on mount (it never changes — a CSS-only
 * signal that JS is alive, not React state): every pre-reveal style is gated
 * behind it, and with JavaScript off the full chapter stands finished — every
 * panel visible, every menu line complete, every neon sign lit.
 */
export default function NightSnackPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>(reduced);

  // One callback ref merges the two refs onto the root node — useReveal
  // observes [data-reveal] descendants.
  const setRootNode = (node: HTMLDivElement | null) => {
    rootRef.current = node;
    revealRef.current = node;
  };

  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    el.classList.add("ns-js");
    window.parent?.postMessage(
      { type: "oneshot:ready", slug: "night-snack" },
      "*",
    );
  }, []);

  return (
    <div
      id="ns-top"
      ref={setRootNode}
      className={`${blackHanSans.variable} ${gaegu.variable} ${notoSansKR.variable} ${spaceMono.variable} ns-root`}
    >
      <Hero />
      <main>
        <SteamScrub />
        <ClinkDrag />
        <NeonSigns />
        <MenuBoard />
      </main>
      <NightFooter />
    </div>
  );
}

/* ==========================================================================
   NIGHT-SNACK — 새벽 한 시의 포장마차 / 1 AM street-food tent
   webtoon · the third twin. NEON · STEAM · STREET-FOOD · pure code (no images).
   Scoped by convention to .ns-root; classes prefixed ns-.
   Distinct from PPANG! (warm dawn bakery, cream paper, generated art) and
   MOONLIT (cold night delivery, indigo, generated art): this one is deep plum
   night + tri-color neon + halftone dots, and every illustration is a CSS/SVG
   shape — no raster payload at all.
   ========================================================================== */

.ns-root {
  /* -- palette ---------------------------------------------------------- */
  --ns-night: #14101c;        /* page ground — back-alley at 1 AM */
  --ns-night-panel: #1d1726;  /* secondary surface — tent wall, menu card */
  --ns-night-high: #271f33;   /* hover/active surface, glass rim */
  --ns-lantern: #fbf3df;      /* primary text — lit paper lantern (14.6:1) */
  --ns-lantern-dim: #c7b8c4;  /* secondary text — tent's quiet voice (8.0:1) */
  --ns-amber: #ffb347;        /* the accent — grill, !, focus, prices (9.4:1) */
  --ns-amber-bright: #ffcf7a; /* neon at full draw — large/non-text only */
  --ns-pink: #ff5e8a;         /* second neon — drinks sign, soju hi (5.0:1) */
  --ns-green: #7ad67a;        /* third neon — soju bottle, clink spark (8.1:1) */
  --ns-steel: #9a8fa6;        /* metadata — numerals, eyebrows (6.0:1) */
  --ns-hairline: #332a40;     /* decorative rules — never carries text */
  --ns-line-amber: rgba(255, 179, 71, 0.22);
  --ns-line-pink: rgba(255, 94, 138, 0.22);
  --ns-line-green: rgba(122, 214, 122, 0.22);

  /* -- type ------------------------------------------------------------- */
  /* Korean is load-bearing: every stack leads with the Korean face so Hangul
     never falls through to a default sans. */
  --ns-font-display: var(--font-display), "Black Han Sans",
    var(--font-kr), system-ui, sans-serif;
  --ns-font-hand: var(--font-hand), "Gaegu", var(--font-kr), cursive;
  --ns-font-ko: var(--font-kr), "Noto Sans KR", system-ui, sans-serif;
  --ns-font-body: var(--font-kr), "Noto Sans KR", system-ui, -apple-system,
    "Segoe UI", sans-serif;
  --ns-font-mono: var(--font-mono), "Space Mono", var(--font-kr),
    "Courier New", monospace;

  /* -- motion ----------------------------------------------------------- */
  --ns-ease: cubic-bezier(0.2, 0.9, 0.25, 1); /* a skewer slapped on the grill */
  --ns-reveal-ms: 650ms;
  --ns-panel-ms: 800ms;

  /* -- geometry --------------------------------------------------------- */
  --ns-frame-w: min(1180px, 92vw);
  --ns-gutter: clamp(20px, 5vw, 64px);

  /* sprite-scrub: written by useSpriteScrub onto the cooking panel.
     Default 0 = raw food / no steam (the no-JS & pre-hydration state shows
     the first frame; reduced motion pins it at 1 = cooked / steam risen). */
  --ns-steam: 0;

  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  background:
    linear-gradient(180deg, var(--ns-night) 0%, var(--ns-night-panel) 100%);
  color: var(--ns-lantern);
  font-family: var(--ns-font-body);
  font-size: clamp(16px, 0.9vw + 11px, 18px);
  line-height: 1.65;
  overflow-x: hidden;
  overflow-x: clip;
}

/* Korean first-class: its own sans, natural breaks, its own rhythm. */
.ns-root :lang(ko) {
  font-family: var(--ns-font-ko);
  word-break: keep-all;
  letter-spacing: 0;
}

/* Amber selection scoped to the entry root — amber ground, night text, so
   the selected ink stays AAA (9.4:1). */
.ns-root ::selection {
  background: var(--ns-amber);
  color: var(--ns-night);
  text-shadow: none;
}

/* Keyboard focus: a haloed amber ring, the grill-glow of the page. */
.ns-root :focus-visible {
  outline: 2px solid var(--ns-amber);
  outline-offset: 3px;
  border-radius: 2px;
  box-shadow: 0 0 0 4px rgba(255, 179, 71, 0.2);
}

.ns-mono {
  font-family: var(--ns-font-mono);
  font-variant-numeric: tabular-nums;
}

/* Visually hidden, still read aloud */
.ns-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ==========================================================================
   Texture — the back-alley night, in three static layers.
   (1) Halftone dot grid: the printed-webtoon Ben-Day field.
   (2) Neon haze: faint per-section blooms (added on the sections themselves).
   (3) Ground gradient: already on the root above.
   None of these animate — the page is ink on newsprint, not a screen.
   ========================================================================== */

.ns-root::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  /* Halftone dots: a radial-gradient tiled into a 14px grid, ~7% lantern
     opacity over the night ground. screen blend so dots add light, the way
     printed dots on newsprint catch the lamp. */
  background-image: radial-gradient(
    circle,
    rgba(251, 243, 223, 0.07) 1.4px,
    transparent 1.6px
  );
  background-size: 14px 14px;
  background-position: 0 0;
  mix-blend-mode: screen;
  opacity: 0.9;
}

/* ==========================================================================
   Shared section furniture
   ========================================================================== */

.ns-eyebrow {
  margin: 0 0 0.7rem;
  font-family: var(--ns-font-mono);
  font-size: 0.76rem;
  letter-spacing: 0.26em;
  color: var(--ns-amber);
  text-transform: uppercase;
}
.ns-eyebrow :lang(ko) {
  font-family: var(--ns-font-ko);
  letter-spacing: 0.04em;
  text-transform: none;
}

.ns-sechead {
  margin: 0 0 clamp(1.4rem, 3vw, 2.2rem);
  font-family: var(--ns-font-display);
  font-weight: 400;
  font-size: clamp(2rem, 5.4vw, 3.4rem);
  line-height: 1.1;
  letter-spacing: 0.01em;
  color: var(--ns-lantern);
}
.ns-sechead__ko {
  display: block;
}
.ns-sechead__en {
  display: block;
  margin-top: 0.18em;
  font-family: var(--ns-font-body);
  font-weight: 500;
  font-size: 0.42em;
  letter-spacing: 0.16em;
  color: var(--ns-amber);
  text-transform: uppercase;
}

/* ==========================================================================
   Reveal primitives — JS-gated pre-state, transform/opacity only
   ========================================================================== */

.ns-js [data-reveal] {
  opacity: 0;
  transform: translateY(16px);
  transition:
    opacity var(--ns-reveal-ms) var(--ns-ease),
    transform var(--ns-reveal-ms) var(--ns-ease);
  will-change: opacity, transform;
}
.ns-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* ==========================================================================
   Chapter 01 — Hero: the tent at 1 AM
   A CSS-drawn pojangmacha: orange tarp roof, striped awning, a row of paper
   lanterns, a counter, steam, and the wordmark 야식! in neon amber. No image.
   ========================================================================== */

.ns-hero {
  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  overflow: hidden;
  isolation: isolate;
}

/* The ambient alley photo — a generated night-food-street render blurred
   deep behind the diorama. The CSS tent stays the foreground; this is the
   back-alley the tent sits in at 1 AM. */
.ns-hero__alley {
  position: absolute;
  inset: -6%;
  width: 112%;
  height: 112%;
  object-fit: cover;
  object-position: center 30%;
  opacity: 0.5;
  filter: blur(3px) saturate(1.15) brightness(0.7);
  z-index: -1;
  pointer-events: none;
}

/* Neon haze over the hero — amber bloom top-right (the grill), pink bloom
   left (the drinks sign). Decorative only. */
.ns-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    radial-gradient(60% 50% at 82% 30%, rgba(255, 179, 71, 0.16) 0%, transparent 60%),
    radial-gradient(50% 45% at 14% 38%, rgba(255, 94, 138, 0.12) 0%, transparent 62%),
    radial-gradient(80% 60% at 50% 100%, rgba(122, 214, 122, 0.06) 0%, transparent 70%);
  pointer-events: none;
}

/* The whole tent diorama lives in one SVG-ish stack of divs. We size it to
   the viewport so the establishing shot owns the first screen. */
.ns-hero__scene {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
}

/* The tarp roof — an orange tent shape, pitched, with a neon edge. */
.ns-hero__roof {
  position: absolute;
  top: 4vh;
  left: 50%;
  width: min(720px, 92vw);
  height: 22vh;
  transform: translateX(-50%);
  background: linear-gradient(180deg, #c9410f 0%, #e85a1e 55%, #b8350d 100%);
  clip-path: polygon(0 100%, 8% 0, 92% 0, 100% 100%);
  filter: drop-shadow(0 0 24px rgba(255, 179, 71, 0.35));
}
/* The neon ridge along the roof's bottom edge — an amber glowing strip. */
.ns-hero__roof::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -3px;
  height: 4px;
  background: var(--ns-amber-bright);
  box-shadow:
    0 0 10px rgba(255, 179, 71, 0.8),
    0 0 24px rgba(255, 179, 71, 0.5);
  border-radius: 2px;
}

/* The striped awning under the roof — red/cream stripes (classic tent). */
.ns-hero__awning {
  position: absolute;
  top: calc(4vh + 20vh);
  left: 50%;
  width: min(740px, 94vw);
  height: 4vh;
  transform: translateX(-50%);
  background: repeating-linear-gradient(
    90deg,
    #d63a1a 0 6%,
    #fbf3df 6% 12%
  );
  clip-path: polygon(
    0 0, 100% 0, 100% 60%,
    96% 100%, 88% 60%, 80% 100%, 72% 60%, 64% 100%,
    56% 60%, 48% 100%, 40% 60%, 32% 100%, 24% 60%,
    16% 100%, 8% 60%, 0 100%
  );
  opacity: 0.95;
}

/* The lantern row — five paper lanterns hanging across the tent mouth. Each
   is a CSS disc with a warm radial glow. They sway on a mutually-prime cycle. */
.ns-hero__lanterns {
  position: absolute;
  top: calc(4vh + 24vh);
  left: 0;
  right: 0;
  display: flex;
  justify-content: space-evenly;
  padding: 0 min(40px, 8vw);
  z-index: 2;
}
.ns-lantern {
  width: clamp(28px, 4.4vw, 52px);
  height: clamp(36px, 5.6vw, 66px);
  border-radius: 50% / 42%;
  background: radial-gradient(
    circle at 42% 38%,
    #fff3c4 0%,
    #ffcf7a 42%,
    #e88a2c 80%,
    #b8350d 100%
  );
  box-shadow:
    0 0 18px rgba(255, 179, 71, 0.65),
    0 0 40px rgba(255, 179, 71, 0.3);
  transform-origin: 50% -40%;
  position: relative;
}
.ns-lantern::before {
  /* the string up to the awning */
  content: "";
  position: absolute;
  left: 50%;
  bottom: 100%;
  width: 1.5px;
  height: clamp(20px, 4vh, 40px);
  background: rgba(251, 243, 223, 0.3);
  transform: translateX(-50%);
}
.ns-lantern:nth-child(1) { animation: ns-sway 5.7s ease-in-out infinite; }
.ns-lantern:nth-child(2) { animation: ns-sway 6.3s ease-in-out infinite 0.4s; }
.ns-lantern:nth-child(3) { animation: ns-sway 5.3s ease-in-out infinite 0.2s; }
.ns-lantern:nth-child(4) { animation: ns-sway 6.7s ease-in-out infinite 0.6s; }
.ns-lantern:nth-child(5) { animation: ns-sway 5.9s ease-in-out infinite 0.3s; }

@keyframes ns-sway {
  0%, 100% { rotate: -0.6deg; }
  50% { rotate: 0.6deg; }
}

/* The counter — a dark bar across the bottom of the diorama, with a warm
   grill ember band along its top edge. */
.ns-hero__counter {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 26vh;
  background: linear-gradient(180deg, #2a1f33 0%, #1a1320 100%);
  border-top: 2px solid var(--ns-night-high);
}
/* The grill ember band — breathes, the only "heat" line on the hero. */
.ns-hero__grill {
  position: absolute;
  left: 12%;
  right: 12%;
  top: -3px;
  height: 6px;
  background: linear-gradient(
    90deg,
    rgba(255, 94, 138, 0.2) 0%,
    var(--ns-amber-bright) 20%,
    #ff7a3a 50%,
    var(--ns-amber-bright) 80%,
    rgba(255, 94, 138, 0.2) 100%
  );
  border-radius: 3px;
  box-shadow:
    0 0 14px rgba(255, 179, 71, 0.7),
    0 0 36px rgba(255, 122, 58, 0.4);
  animation: ns-grill-breath 3.1s ease-in-out infinite;
}
@keyframes ns-grill-breath {
  0%, 100% { opacity: 0.72; }
  50% { opacity: 1; }
}

/* Hero steam — three rising plumes off the grill, decorative. */
.ns-hero__steam {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 24vh;
  height: 30vh;
  pointer-events: none;
  opacity: 0.5;
}
.ns-hero__steam span {
  position: absolute;
  bottom: 0;
  width: 26px;
  height: 90%;
  background: radial-gradient(
    ellipse at 50% 100%,
    rgba(251, 243, 223, 0.5) 0%,
    rgba(251, 243, 223, 0.18) 40%,
    transparent 75%
  );
  filter: blur(6px);
  animation: ns-steam-rise 5.2s ease-in-out infinite;
}
.ns-hero__steam span:nth-child(1) { left: 26%; animation-delay: 0s; }
.ns-hero__steam span:nth-child(2) { left: 48%; animation-delay: 1.1s; }
.ns-hero__steam span:nth-child(3) { left: 68%; animation-delay: 2.3s; }
@keyframes ns-steam-rise {
  0% { transform: translateY(20px) scaleY(0.9); opacity: 0; }
  30% { opacity: 0.7; }
  100% { transform: translateY(-40px) scaleY(1.2); opacity: 0; }
}

/* The hero text — lower third over a dark scrim so the lantern-white reads
   AA over every band of the diorama. */
.ns-hero__inner {
  position: relative;
  z-index: 5;
  width: 100%;
  max-width: var(--ns-frame-w);
  margin: 0 auto;
  padding: 0 var(--ns-gutter) clamp(72px, 12svh, 130px);
  background: linear-gradient(
    180deg,
    rgba(20, 16, 28, 0) 0%,
    rgba(20, 16, 28, 0.5) 40%,
    rgba(20, 16, 28, 0.86) 100%
  );
}

.ns-hero__kicker {
  margin: 0 0 clamp(0.8rem, 2svh, 1.4rem);
  font-family: var(--ns-font-mono);
  font-size: 0.82rem;
  letter-spacing: 0.22em;
  color: var(--ns-lantern-dim);
  text-transform: uppercase;
}
.ns-hero__kicker :lang(ko) {
  font-family: var(--ns-font-ko);
  letter-spacing: 0.04em;
  color: var(--ns-amber);
  text-transform: none;
  margin-right: 0.6em;
}

.ns-hero__title {
  margin: 0;
  line-height: 0.9;
  letter-spacing: 0.01em;
}
.ns-hero__title-ko {
  display: block;
  font-family: var(--ns-font-display);
  font-size: clamp(4.4rem, 20vw, 14rem);
  color: var(--ns-lantern);
  /* the neon glow on the wordmark — amber halo, pink underglow */
  text-shadow:
    0 0 14px rgba(255, 179, 71, 0.55),
    0 0 38px rgba(255, 179, 71, 0.3),
    0 0 60px rgba(255, 94, 138, 0.18);
}
.ns-hero__title-en {
  display: block;
  margin-top: 0.12em;
  font-family: var(--ns-font-mono);
  font-weight: 700;
  font-size: clamp(1.2rem, 4.6vw, 3rem);
  letter-spacing: 0.1em;
  color: var(--ns-amber);
  text-shadow: 0 0 16px rgba(255, 179, 71, 0.4);
}

.ns-hero__lede {
  max-width: 32em;
  margin: clamp(1rem, 2.4svh, 1.6rem) 0 0.4rem;
  font-size: clamp(1.05rem, 1.8vw, 1.3rem);
  line-height: 1.45;
  font-weight: 500;
  color: var(--ns-lantern);
}
.ns-hero__lede-en {
  max-width: 36em;
  margin: 0 0 clamp(1.4rem, 3svh, 2.2rem);
  font-size: 0.94rem;
  color: var(--ns-lantern-dim);
}

.ns-hero__status {
  display: inline-flex;
  align-items: center;
  gap: 0.6em;
  margin: 0;
  padding: 0.5em 0.9em;
  font-family: var(--ns-font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  color: var(--ns-lantern-dim);
  border: 1px solid var(--ns-hairline);
  border-radius: 2px;
  background: rgba(29, 23, 38, 0.6);
}
.ns-hero__status :lang(ko) {
  font-family: var(--ns-font-ko);
  letter-spacing: 0.04em;
}
.ns-hero__statusdot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ns-amber);
  box-shadow: 0 0 8px rgba(255, 179, 71, 0.8);
}
.ns-js .ns-hero__statusdot {
  animation: ns-pulse 2s ease-in-out infinite;
}
@keyframes ns-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.55; transform: scale(0.88); }
}

.ns-hero__hint {
  position: absolute;
  bottom: clamp(18px, 4svh, 30px);
  left: 50%;
  transform: translateX(-50%);
  z-index: 5;
  margin: 0;
  font-family: var(--ns-font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.24em;
  color: var(--ns-steel);
  text-transform: uppercase;
}
.ns-hero__hint :lang(ko) {
  font-family: var(--ns-font-ko);
  letter-spacing: 0.04em;
  margin-right: 0.4em;
  text-transform: none;
}

/* ==========================================================================
   Chapter 02 — SteamScrub: the cooking sprite sequence
   A pinned-tall panel whose scroll progress scrubs a stack of frames — each a
   pure CSS/SVG drawing of steam + halftone density at a different phase. The
   `sprite-scrub` technique, with code-drawn sprites instead of an image strip.
   ========================================================================== */

.ns-cook {
  position: relative;
  padding: clamp(80px, 12svh, 150px) var(--ns-gutter)
    clamp(60px, 10svh, 120px);
}
.ns-cook__intro {
  max-width: var(--ns-frame-w);
  margin: 0 auto clamp(2rem, 5svh, 3rem);
}
.ns-cook__intro p {
  max-width: 38em;
  margin: 0;
  font-size: 0.98rem;
  color: var(--ns-lantern-dim);
}
.ns-cook__intro p :lang(ko) {
  display: block;
  color: var(--ns-lantern);
  margin-bottom: 0.4em;
}

/* The stage: taller than the viewport so there is scroll to scrub through.
   The frames live inside, absolutely positioned. */
.ns-cook__stage {
  position: relative;
  max-width: min(960px, 92vw);
  margin: 0 auto;
  /* Tall enough to scrub meaningfully; the observer-driven hook maps the
     panel's viewport travel onto [0,1]. */
  min-height: 78vh;
  border: 1px solid var(--ns-hairline);
  background:
    radial-gradient(80% 60% at 50% 40%, rgba(255, 179, 71, 0.06) 0%, transparent 70%),
    var(--ns-night-panel);
  overflow: hidden;
  isolation: isolate;
}

/* The skewer/grill base — present in every frame, the anchor. */
.ns-cook__grill {
  position: absolute;
  left: 50%;
  bottom: 14%;
  width: 70%;
  height: 10%;
  transform: translateX(-50%);
  background: linear-gradient(180deg, #3a2230 0%, #1a1018 100%);
  border-top: 3px solid var(--ns-amber);
  border-radius: 4px;
  box-shadow: 0 0 24px rgba(255, 179, 71, 0.3);
}
/* The skewers lying across the grill — three sticks with food. */
.ns-cook__skewer {
  position: absolute;
  left: 50%;
  bottom: calc(14% + 4%);
  width: 60%;
  height: 3px;
  transform: translateX(-50%);
  background: linear-gradient(90deg, #6b4a2c, #8a5e36, #6b4a2c);
  border-radius: 2px;
}
.ns-cook__skewer--2 { bottom: calc(14% + 7%); width: 64%; }
.ns-cook__skewer--3 { bottom: calc(14% + 10%); width: 58%; }
/* The food chunks on each skewer — their color shifts raw → cooked by frame
   via the parent's data-frame and the --ns-steam scrub. We tint with filter
   so we never restyle layout. */
.ns-cook__chunk {
  position: absolute;
  top: -7px;
  width: 16px;
  height: 16px;
  border-radius: 40%;
  background: #b5602c;
  filter: brightness(0.7) saturate(0.7);
  transition: none;
}

/* The frames. Each is a full-cover layer; only its opacity is driven by
   --ns-steam. We render frames as sibling divs whose opacity is a triangular
   window around a center point p_i ∈ [0,1], built from max()/min() so we
   avoid abs() (uneven support). With N frames, frame i centers at i/(N-1),
   and is fully visible in a window of ~1/(N-1) around that center. */
.ns-cook__frame {
  position: absolute;
  inset: 0;
  pointer-events: none;
  /* frame-local var set per-frame by inline style: --ns-c (center) and
     --ns-h (half-window). Opacity = 1 - clamp(|steam - c| / h, 0, 1). */
  opacity: calc(
    1 - clamp(
      max(var(--ns-steam) - var(--ns-c, 0), var(--ns-c, 0) - var(--ns-steam)) / var(--ns-h, 0.2),
      0,
      1
    )
  );
}

/* Frame contents: a steam plume (different size/position per frame) + a
   halftone-dot density field (more dots = more heat). All CSS. */
.ns-cook__plume {
  position: absolute;
  left: 50%;
  bottom: 22%;
  width: 46%;
  height: 50%;
  transform: translateX(-50%);
  background: radial-gradient(
    ellipse 60% 80% at 50% 100%,
    rgba(251, 243, 223, 0.5) 0%,
    rgba(251, 243, 223, 0.18) 45%,
    transparent 78%
  );
  filter: blur(7px);
}
/* The halftone heat field — denser dots = hotter grill. Each frame ships its
   own dot size via inline style; this rule just sets the field. */
.ns-cook__heat {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(
    circle,
    rgba(255, 179, 71, 0.32) 1px,
    transparent 1.6px
  );
  mix-blend-mode: screen;
}

/* Overlaid labels: phase name + SFX, per frame-set. We show the label group
   whose window is active by the same opacity math. */
.ns-cook__labels {
  position: absolute;
  top: clamp(16px, 3vw, 28px);
  left: clamp(16px, 3vw, 28px);
  z-index: 3;
  pointer-events: none;
}
.ns-cook__label {
  position: absolute;
  inset: 0;
  opacity: calc(
    1 - clamp(
      max(var(--ns-steam) - var(--ns-c, 0), var(--ns-c, 0) - var(--ns-steam)) / var(--ns-h, 0.2),
      0,
      1
    )
  );
}
.ns-cook__phase {
  margin: 0;
  font-family: var(--ns-font-mono);
  font-size: 0.74rem;
  letter-spacing: 0.18em;
  color: var(--ns-amber);
  text-transform: uppercase;
}
.ns-cook__phase :lang(ko) {
  font-family: var(--ns-font-ko);
  letter-spacing: 0.04em;
  text-transform: none;
}
/* SFX stamp, webtoon-style */
.ns-cook__sfx {
  position: absolute;
  top: clamp(18px, 4vw, 34px);
  right: clamp(16px, 3vw, 28px);
  z-index: 3;
  font-family: var(--ns-font-display);
  font-size: clamp(1.6rem, 3.6vw, 2.4rem);
  color: var(--ns-amber-bright);
  text-shadow: 0 0 14px rgba(255, 179, 71, 0.6);
  rotate: -6deg;
  pointer-events: none;
  opacity: calc(
    1 - clamp(
      max(var(--ns-steam) - var(--ns-c, 0), var(--ns-c, 0) - var(--ns-steam)) / var(--ns-h, 0.2),
      0,
      1
    )
  );
}

/* The scrub rail — a vertical progress bar on the right of the stage, the
   page's honesty about "this is scrubbed by your scroll". */
.ns-cook__rail {
  position: absolute;
  right: clamp(10px, 2vw, 18px);
  top: 12%;
  bottom: 12%;
  width: 3px;
  background: var(--ns-hairline);
  z-index: 4;
  pointer-events: none;
}
.ns-cook__rail-fill {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: calc(var(--ns-steam, 0) * 100%);
  background: var(--ns-amber);
  box-shadow: 0 0 10px rgba(255, 179, 71, 0.6);
}

.ns-cook__hint {
  margin: clamp(1rem, 2.4svh, 1.4rem) auto 0;
  max-width: min(960px, 92vw);
  font-family: var(--ns-font-mono);
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  color: var(--ns-steel);
}
.ns-cook__hint :lang(ko) {
  font-family: var(--ns-font-ko);
  color: var(--ns-lantern-dim);
  margin-right: 0.5em;
}

/* ==========================================================================
   Chapter 03 — ClinkDrag: the soju table (drag-physics)
   A stage of draggable soju glasses + a skewer you can fling and clink.
   ========================================================================== */

.ns-clink {
  position: relative;
  padding: clamp(80px, 12svh, 150px) var(--ns-gutter)
    clamp(60px, 10svh, 120px);
  background:
    radial-gradient(60% 50% at 50% 50%, rgba(122, 214, 122, 0.05) 0%, transparent 70%),
    transparent;
}
.ns-clink__intro {
  max-width: var(--ns-frame-w);
  margin: 0 auto clamp(1.4rem, 3svh, 2rem);
}
.ns-clink__intro p {
  max-width: 38em;
  margin: 0;
  font-size: 0.98rem;
  color: var(--ns-lantern-dim);
}
.ns-clink__intro p :lang(ko) {
  display: block;
  color: var(--ns-lantern);
  margin-bottom: 0.4em;
}

/* The table — a dark wood surface, the play area. Sized in px so the physics
   (which is px-based) is stable. Height is viewport-coupled but clamped. */
.ns-clink__table {
  position: relative;
  max-width: min(900px, 92vw);
  margin: 0 auto;
  height: clamp(360px, 56vh, 540px);
  border: 1px solid var(--ns-hairline);
  border-radius: 6px;
  background:
    repeating-linear-gradient(
      90deg,
      rgba(58, 40, 30, 0.4) 0 2px,
      transparent 2px 22px
    ),
    linear-gradient(180deg, #2a1d28 0%, #18101a 100%);
  overflow: hidden;
  isolation: isolate;
  /* Only fine pointers get the drag; touch sees the calm table. */
  touch-action: none;
}
/* A faint wipe sheen on the table. */
.ns-clink__table::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    80% 60% at 40% 30%,
    rgba(251, 243, 223, 0.04) 0%,
    transparent 60%
  );
  pointer-events: none;
}

/* A draggable body. Position is set inline by useClinkPhysics (translate3d),
   so these rules only carry the visual. */
.ns-clink-body {
  position: absolute;
  top: 0;
  left: 0;
  width: 0;
  height: 0;
  cursor: grab;
  touch-action: none;
  user-select: none;
  will-change: transform;
}
.ns-clink-body:focus-visible {
  /* The body is a div; give it a real focus outline (keyboard can reach it
     via tabindex=0 set in the component). The halo sits around the glass. */
  outline: 2px solid var(--ns-amber);
  outline-offset: 8px;
  border-radius: 50%;
}
.ns-clink-body.is-grabbed {
  cursor: grabbing;
}

/* The soju glass — a CSS drawing: green bottle silhouette + clear glass. */
.ns-glass {
  position: relative;
  width: 40px;
  height: 56px;
  margin: -28px 0 0 -20px;
  filter: drop-shadow(0 6px 10px rgba(0, 0, 0, 0.5));
}
/* The glass cup: trapezoid, faintly luminous soju-green tint. */
.ns-glass__cup {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 36px;
  height: 38px;
  background: linear-gradient(
    180deg,
    rgba(122, 214, 122, 0.32) 0%,
    rgba(122, 214, 122, 0.6) 100%
  );
  border: 1.5px solid var(--ns-green);
  border-top: none;
  border-radius: 0 0 6px 6px;
  clip-path: polygon(8% 0, 92% 0, 82% 100%, 18% 100%);
  box-shadow: 0 0 12px rgba(122, 214, 122, 0.4);
}
/* The liquid surface line */
.ns-glass__cup::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 8%;
  right: 8%;
  height: 2px;
  background: rgba(251, 243, 223, 0.5);
  border-radius: 50%;
}
/* The soju bottle behind, peeking up — green silhouette. */
.ns-glass__bottle {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 14px;
  height: 24px;
  background: linear-gradient(180deg, #4a9c4a 0%, #2e6e2e 100%);
  border-radius: 3px 3px 0 0;
}
.ns-glass__bottle::before {
  /* the cap */
  content: "";
  position: absolute;
  top: -5px;
  left: 50%;
  transform: translateX(-50%);
  width: 12px;
  height: 6px;
  background: #1f4a1f;
  border-radius: 2px 2px 0 0;
}

/* A skewer body — horizontal stick with food chunks. */
.ns-skewer-body {
  position: relative;
  width: 120px;
  height: 22px;
  margin: -11px 0 0 -60px;
  cursor: grab;
  touch-action: none;
  user-select: none;
  will-change: transform;
  filter: drop-shadow(0 4px 8px rgba(0, 0, 0, 0.5));
}
.ns-skewer-body:focus-visible {
  outline: 2px solid var(--ns-amber);
  outline-offset: 6px;
  border-radius: 4px;
}
.ns-skewer-body.is-grabbed {
  cursor: grabbing;
}
.ns-skewer-body__stick {
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 3px;
  transform: translateY(-50%);
  background: linear-gradient(90deg, #6b4a2c, #9a6e3e, #6b4a2c);
  border-radius: 2px;
}
.ns-skewer-body__chunk {
  position: absolute;
  top: 50%;
  width: 18px;
  height: 18px;
  transform: translate(-50%, -50%);
  border-radius: 40%;
  background: #b5602c;
  box-shadow: inset -2px -2px 4px rgba(0, 0, 0, 0.3);
}

/* The clink spark SFX — a webtoon starburst that pops at the clink point and
   fades. Rendered by React at the clink coordinate. */
.ns-spark {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  z-index: 6;
  animation: ns-spark-pop 520ms var(--ns-ease) forwards;
}
.ns-spark::before,
.ns-spark::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 70px;
  height: 70px;
  transform: translate(-50%, -50%);
  background:
    radial-gradient(circle, rgba(255, 207, 122, 0.9) 0%, rgba(255, 94, 138, 0.4) 40%, transparent 70%);
  border-radius: 50%;
  filter: blur(2px);
}
.ns-spark::after {
  width: 30px;
  height: 30px;
  background: radial-gradient(circle, #fff 0%, var(--ns-amber-bright) 60%, transparent 100%);
}
.ns-spark__sfx {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--ns-font-display);
  font-size: 1.5rem;
  color: var(--ns-amber-bright);
  text-shadow: 0 0 12px rgba(255, 179, 71, 0.7);
  white-space: nowrap;
  rotate: -8deg;
}
@keyframes ns-spark-pop {
  0% { opacity: 0; transform: scale(0.4); }
  30% { opacity: 1; transform: scale(1.15); }
  100% { opacity: 0; transform: scale(1.5); }
}

/* Instruction caption inside the table, top-left, decorative. */
.ns-clink__cap {
  position: absolute;
  top: clamp(12px, 2.4vw, 20px);
  left: clamp(12px, 2.4vw, 20px);
  z-index: 4;
  margin: 0;
  font-family: var(--ns-font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  color: var(--ns-steel);
  text-transform: uppercase;
  pointer-events: none;
}
.ns-clink__cap :lang(ko) {
  font-family: var(--ns-font-ko);
  letter-spacing: 0.04em;
  color: var(--ns-lantern-dim);
  margin-right: 0.5em;
  text-transform: none;
}

/* ==========================================================================
   Chapter 04 — NeonSigns: the ASCII-art neon signboard (ascii-render)
   ========================================================================== */

.ns-signs {
  position: relative;
  padding: clamp(80px, 12svh, 150px) var(--ns-gutter)
    clamp(60px, 10svh, 120px);
  background:
    radial-gradient(60% 50% at 30% 40%, rgba(255, 94, 138, 0.06) 0%, transparent 65%),
    radial-gradient(60% 50% at 70% 60%, rgba(122, 214, 122, 0.05) 0%, transparent 65%);
}
.ns-signs__intro {
  max-width: var(--ns-frame-w);
  margin: 0 auto clamp(1.6rem, 4svh, 2.4rem);
}
.ns-signs__intro p {
  max-width: 40em;
  margin: 0;
  font-size: 0.98rem;
  color: var(--ns-lantern-dim);
}
.ns-signs__intro p :lang(ko) {
  display: block;
  color: var(--ns-lantern);
  margin-bottom: 0.4em;
}

.ns-signs__grid {
  max-width: var(--ns-frame-w);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(1rem, 2vw, 1.6rem);
}
@media (max-width: 820px) {
  .ns-signs__grid {
    grid-template-columns: 1fr;
  }
}

/* One ASCII sign card: a dark "lightbox" with the ASCII glyphs glowing. */
.ns-ascii {
  position: relative;
  padding: clamp(1.1rem, 2.4svh, 1.6rem);
  border: 1px solid var(--ns-hairline);
  background:
    radial-gradient(80% 70% at 50% 50%, rgba(0, 0, 0, 0.4) 0%, transparent 80%),
    var(--ns-night-panel);
  border-radius: 4px;
  overflow: hidden;
  isolation: isolate;
}
/* The faint neon haze behind each sign, colored per-sign. */
.ns-ascii::before {
  content: "";
  position: absolute;
  inset: -20%;
  z-index: 0;
  background: radial-gradient(circle, var(--ns-glow, rgba(255, 179, 71, 0.16)) 0%, transparent 60%);
  pointer-events: none;
}
.ns-ascii--amber { --ns-glow: rgba(255, 179, 71, 0.18); }
.ns-ascii--pink { --ns-glow: rgba(255, 94, 138, 0.18); }
.ns-ascii--green { --ns-glow: rgba(122, 214, 122, 0.16); }

.ns-ascii__head {
  position: relative;
  z-index: 2;
  margin: 0 0 0.8rem;
  font-family: var(--ns-font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.2em;
  color: var(--ns-steel);
  text-transform: uppercase;
}
.ns-ascii__head :lang(ko) {
  font-family: var(--ns-font-ko);
  letter-spacing: 0.04em;
  text-transform: none;
  color: var(--ns-lantern-dim);
  margin-right: 0.5em;
}

/* The ASCII block — pre, monospace, the glyphs carry the glow + flicker. */
.ns-ascii__pre {
  position: relative;
  z-index: 2;
  margin: 0;
  font-family: var(--ns-font-mono);
  font-size: clamp(8px, 1.4vw, 13px);
  line-height: 1.1;
  letter-spacing: 0;
  color: transparent;
  white-space: pre;
  overflow: hidden;
  text-align: center;
}
.ns-ascii__c {
  display: inline-block;
  color: var(--ns-ascii-color, var(--ns-amber-bright));
  text-shadow:
    0 0 4px var(--ns-ascii-glow, rgba(255, 179, 71, 0.9)),
    0 0 10px var(--ns-ascii-glow, rgba(255, 179, 71, 0.5));
  transition: opacity 90ms linear;
}
.ns-ascii--amber .ns-ascii__c {
  --ns-ascii-color: var(--ns-amber-bright);
  --ns-ascii-glow: rgba(255, 179, 71, 0.9);
}
.ns-ascii--pink .ns-ascii__c {
  --ns-ascii-color: #ff8fb0;
  --ns-ascii-glow: rgba(255, 94, 138, 0.9);
}
.ns-ascii--green .ns-ascii__c {
  --ns-ascii-color: #a6e6a6;
  --ns-ascii-glow: rgba(122, 214, 122, 0.9);
}
/* The flicker — a cell the hook marked is-dim drops opacity + glow. */
.ns-ascii__c.is-dim {
  opacity: 0.28;
  text-shadow: none;
}
/* A "space" cell stays invisible regardless (the empty parts of the ASCII). */
.ns-ascii__c.is-space {
  color: transparent;
  text-shadow: none;
  opacity: 1;
}

.ns-ascii__caption {
  position: relative;
  z-index: 2;
  margin: 0.9rem 0 0;
  font-size: 0.84rem;
  color: var(--ns-lantern-dim);
}
.ns-ascii__caption :lang(ko) {
  display: block;
  color: var(--ns-lantern);
  margin-bottom: 0.2em;
  font-family: var(--ns-font-hand);
  font-size: 1.05em;
}

/* ==========================================================================
   Chapter 05 — MenuBoard: the 오늘의 메뉴 (no-JS-readable)
   The menu is plain semantic HTML; it is fully readable with JS off.
   ========================================================================== */

.ns-menu {
  padding: clamp(80px, 12svh, 150px) var(--ns-gutter)
    clamp(60px, 10svh, 120px);
  border-top: 1px solid var(--ns-hairline);
}
.ns-menu__inner {
  max-width: min(760px, 92vw);
  margin: 0 auto;
}
.ns-menu__head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.4em 1rem;
  margin-bottom: clamp(1.4rem, 3svh, 2rem);
  padding-bottom: 0.8rem;
  border-bottom: 2px solid var(--ns-amber);
}
.ns-menu__title {
  margin: 0;
  font-family: var(--ns-font-display);
  font-size: clamp(1.8rem, 4.4vw, 2.8rem);
  line-height: 1;
  color: var(--ns-lantern);
}
.ns-menu__date {
  margin: 0 0 0 auto;
  font-family: var(--ns-font-mono);
  font-size: 0.8rem;
  letter-spacing: 0.1em;
  color: var(--ns-steel);
}

.ns-menu__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0;
}
.ns-menu__row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 0.6rem 1rem;
  align-items: baseline;
  padding: clamp(0.9rem, 2svh, 1.2rem) 0.2rem;
  border-bottom: 1px dashed var(--ns-hairline);
}
.ns-menu__row:last-child {
  border-bottom: none;
}
.ns-menu__no {
  font-family: var(--ns-font-mono);
  font-size: 0.78rem;
  color: var(--ns-steel);
  letter-spacing: 0.1em;
}
.ns-menu__name {
  display: flex;
  flex-direction: column;
  gap: 0.1em;
}
.ns-menu__name :lang(ko) {
  font-family: var(--ns-font-ko);
  font-weight: 500;
  font-size: 1.04rem;
  color: var(--ns-lantern);
}
.ns-menu__name-en {
  font-size: 0.84rem;
  color: var(--ns-lantern-dim);
}
.ns-menu__price {
  font-family: var(--ns-font-mono);
  font-weight: 700;
  font-size: 1.02rem;
  color: var(--ns-amber);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.ns-menu__tag {
  display: inline-block;
  margin-left: 0.5em;
  padding: 0.1em 0.5em;
  font-family: var(--ns-font-mono);
  font-size: 0.66rem;
  letter-spacing: 0.08em;
  color: var(--ns-green);
  border: 1px solid var(--ns-line-green);
  border-radius: 2px;
  vertical-align: middle;
}
.ns-menu__tag--hot {
  color: var(--ns-pink);
  border-color: var(--ns-line-pink);
}

.ns-menu__note {
  margin: clamp(1.4rem, 3svh, 2rem) 0 0;
  padding: clamp(1rem, 2svh, 1.4rem);
  border: 1px solid var(--ns-hairline);
  background: rgba(29, 23, 38, 0.5);
  border-radius: 4px;
  font-size: 0.92rem;
  color: var(--ns-lantern-dim);
}
.ns-menu__note :lang(ko) {
  display: block;
  color: var(--ns-lantern);
  margin-bottom: 0.3em;
  font-family: var(--ns-font-hand);
  font-size: 1.1em;
}

@media (max-width: 460px) {
  .ns-menu__row {
    grid-template-columns: auto 1fr;
  }
  .ns-menu__price {
    grid-column: 1 / -1;
    padding-left: 2.4rem;
  }
}

/* ==========================================================================
   Chapter 06 — NightFooter: hours, address, sign-off
   ========================================================================== */

.ns-foot {
  padding: clamp(70px, 10svh, 130px) var(--ns-gutter)
    clamp(48px, 7svh, 80px);
  border-top: 1px solid var(--ns-hairline);
  background:
    radial-gradient(60% 50% at 50% 0%, rgba(255, 179, 71, 0.05) 0%, transparent 60%),
    var(--ns-night);
}
.ns-foot__inner {
  max-width: var(--ns-frame-w);
  margin: 0 auto;
}
.ns-foot__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(1.2rem, 3vw, 2.4rem);
  margin-bottom: clamp(2rem, 5svh, 3rem);
}
@media (max-width: 760px) {
  .ns-foot__grid {
    grid-template-columns: 1fr;
  }
}
.ns-foot__cellk {
  margin: 0 0 0.5rem;
  font-family: var(--ns-font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  color: var(--ns-steel);
  text-transform: uppercase;
}
.ns-foot__cellv {
  margin: 0 0 0.5rem;
}
.ns-foot__cellv :lang(ko) {
  display: block;
  font-family: var(--ns-font-ko);
  font-size: clamp(1.05rem, 1.9vw, 1.3rem);
  font-weight: 700;
  color: var(--ns-lantern);
}
.ns-foot__cellen {
  font-family: var(--ns-font-mono);
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  color: var(--ns-amber);
}
.ns-foot__celln {
  margin: 0;
  font-size: 0.92rem;
  line-height: 1.55;
  color: var(--ns-lantern);
}
.ns-foot__celln :lang(ko) {
  font-family: var(--ns-font-ko);
}
.ns-foot__celln-en {
  margin: 0;
  font-size: 0.85rem;
  line-height: 1.5;
  color: var(--ns-lantern-dim);
  font-style: italic;
}

.ns-foot__koan {
  max-width: 44rem;
  margin: clamp(1.6rem, 3svh, 2.4rem) 0;
  padding: clamp(1.2rem, 2.6svh, 1.8rem) 0;
  border-top: 1px solid var(--ns-hairline);
  border-bottom: 1px solid var(--ns-hairline);
}
.ns-foot__koan :lang(ko) {
  display: block;
  font-family: var(--ns-font-hand);
  font-size: clamp(1.2rem, 2.6vw, 1.7rem);
  line-height: 1.4;
  color: var(--ns-lantern);
  margin-bottom: 0.4em;
}
.ns-foot__koan-en {
  font-style: italic;
  font-size: 0.96rem;
  color: var(--ns-lantern-dim);
}

.ns-foot__base {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem 2rem;
  align-items: center;
  padding-top: clamp(1.2rem, 2svh, 1.6rem);
  border-top: 1px solid var(--ns-hairline);
}
.ns-foot__brand :lang(ko) {
  font-family: var(--ns-font-display);
  font-size: 1.4rem;
  color: var(--ns-amber);
  text-shadow: 0 0 14px rgba(255, 179, 71, 0.4);
}
.ns-foot__branden {
  margin-left: 0.6em;
  font-family: var(--ns-font-mono);
  font-size: 0.74rem;
  letter-spacing: 0.2em;
  color: var(--ns-steel);
}
.ns-foot__copy {
  font-family: var(--ns-font-mono);
  font-size: 0.74rem;
  letter-spacing: 0.08em;
  color: var(--ns-steel);
}
.ns-foot__top {
  font-family: var(--ns-font-mono);
  font-size: 0.74rem;
  letter-spacing: 0.18em;
  color: var(--ns-amber);
  text-decoration: none;
  margin-left: auto;
}
.ns-foot__top:hover {
  color: var(--ns-amber-bright);
}

/* ==========================================================================
   Keyframes — transform / opacity / filter only
   ========================================================================== */

/* ==========================================================================
   Reduced motion — a complete, calm, static page.
   The neon signs hold steady (no flicker); steam holds its final frame (food
   cooked, plume fully risen); the clink stage is a calm table (no drag); the
   lanterns and grill are still. Nothing depends on JS to be readable.
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .ns-root {
    /* pin the scrub at the cooked/risen end state */
    --ns-steam: 1;
  }

  .ns-lantern,
  .ns-hero__grill,
  .ns-hero__steam span,
  .ns-hero__statusdot {
    animation: none !important;
  }

  .ns-js [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .ns-ascii__c.is-dim {
    /* signs hold full, steady brightness */
    opacity: 1;
    text-shadow:
      0 0 4px var(--ns-ascii-glow, rgba(255, 179, 71, 0.9)),
      0 0 10px var(--ns-ascii-glow, rgba(255, 179, 71, 0.5));
  }

  .ns-spark {
    animation: none;
    opacity: 0;
  }
}

/* ==========================================================================
   Print — a quiet poster of the tent
   ========================================================================== */

@media print {
  .ns-root::before {
    display: none;
  }
  .ns-lantern,
  .ns-hero__grill,
  .ns-hero__steam span {
    animation: none;
  }
}
